# fg connected comps; map seeds
unseen={(r,c) for r in range(H) for c in range(W) if fg[r][c]}
compid={}; comps=[]
while unseen:
 start=unseen.pop(); q=[start]; ccset={start};
 while q:
  r,c=q.pop()
  for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
   if p in unseen: unseen.remove(p);ccset.add(p);q.append(p)
 cid=len(comps);comps.append(ccset)
 for p in ccset: compid[p]=cid
[(s,compid[(s[0],s[1])],sorted(v for r,c in comps[compid[(s[0],s[1])]] for v in [G[r][c]] if v>1)) for s in seeds], [(i,len(x),sorted(set(G[r][c] for r,c in x if G[r][c]>1))) for i,x in enumerate(comps)]
